package com.laptopshop.controller; import com.laptopshop.dto.*; import com.laptopshop.entity.*; import com.laptopshop.exception.*; import com.laptopshop.service.*; import jakarta.validation.Valid; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.validation.BindingResult; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.mvc.support.RedirectAttributes;
@Controller @RequestMapping("/admin/brands") public class BrandController { private final BrandService service; public BrandController(BrandService s){service=s;}
 @GetMapping public String list(@RequestParam(defaultValue="") String keyword,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="10") int size,@RequestParam(defaultValue="name") String sortBy,@RequestParam(defaultValue="asc") String direction,Model m){var p=service.getBrands(keyword,page,size,sortBy,direction);m.addAttribute("brandPage",p);m.addAttribute("keyword",keyword);m.addAttribute("sortBy",sortBy);m.addAttribute("direction",direction);return "brands/list";}
 @GetMapping("/add") public String add(Model m){m.addAttribute("brandDTO",new BrandDTO());m.addAttribute("isEdit",false);return "brands/form";}
 @PostMapping("/add") public String create(@Valid @ModelAttribute BrandDTO brandDTO,BindingResult br,Model m,RedirectAttributes ra){if(br.hasErrors()){m.addAttribute("isEdit",false);return "brands/form";}try{service.createBrand(brandDTO);ra.addFlashAttribute("successMessage","Thêm thương hiệu thành công");return "redirect:/admin/brands";}catch(RuntimeException e){m.addAttribute("errorMessage",e.getMessage());m.addAttribute("isEdit",false);return "brands/form";}}
 @GetMapping("/edit/{id}") public String edit(@PathVariable Integer id,Model m,RedirectAttributes ra){try{Brand b=service.getBrandById(id);BrandDTO d=new BrandDTO();d.setId(b.getId());d.setName(b.getName());d.setCountry(b.getCountry());d.setDescription(b.getDescription());d.setIsActive(b.getIsActive());m.addAttribute("brandDTO",d);m.addAttribute("isEdit",true);return "brands/form";}catch(RuntimeException e){ra.addFlashAttribute("errorMessage",e.getMessage());return "redirect:/admin/brands";}}
 @PostMapping("/edit/{id}") public String update(@PathVariable Integer id,@Valid @ModelAttribute BrandDTO brandDTO,BindingResult br,Model m,RedirectAttributes ra){if(br.hasErrors()){m.addAttribute("isEdit",true);return "brands/form";}try{service.updateBrand(id,brandDTO);ra.addFlashAttribute("successMessage","Cập nhật thương hiệu thành công");return "redirect:/admin/brands";}catch(RuntimeException e){m.addAttribute("errorMessage",e.getMessage());m.addAttribute("isEdit",true);return "brands/form";}}
 @PostMapping("/delete/{id}") public String delete(@PathVariable Integer id,RedirectAttributes ra){try{service.deleteBrand(id);ra.addFlashAttribute("successMessage","Xóa thương hiệu thành công");}catch(RuntimeException e){ra.addFlashAttribute("errorMessage",e.getMessage());}return "redirect:/admin/brands";}}
